new:
alue::Array(values) => values.iter().for_each(|value| explicit_events(value, events)),
        Value::Object(values) => values
            .values()
            .for_each(|value| explicit_events(value, events)),
        Value::Null | Value::Bool(_) | Value::Number(_) => {}
    }
}

fn progress(step: &str, detail: &str) -> String {
    json!({"type":"progress","step":step,"detail":detail}).to_string()
}

fn tool_action(tool: &str) -> String {
    json!({
        "type":"tool_action",
        "tool":tool,
        "action":"provider tool invocation",
        "success":Value::Null
    })
    .to_string()
}

fn direct_args(text: &str) -> Vec<String> {
    text.split_whitespace().map(ToOwned::to_owned).collect()
}

fn os_args(args: &[&str]) -> Vec<OsString> {
    args.iter().map(OsString::from).collect()
}

fn probe_first_class(
    program: &OsStr,
    version_args: &[&str],
    auth_args: &[&str],
) -> ExternalAgentProviderStatus {
    if !command_output(program, version_args).is_some_and(|(success, _)| success) {
        return ExternalAgentProviderStatus {
            discovered: false,
            auth: ProviderAuthStatus::Unknown,
        };
    }
    let auth = command_output(program, auth_args)
        .map(|(success, output)| {
            if success {
                ProviderAuthStatus::Authenticated
            } else if ["not logged in", "login", "authentication", "unauthorized"]
                .iter()
                .any(|needle| output.to_ascii_lowercase().contains(needle))
            {
                ProviderAuthStatus::NotAuthenticated
            } else {
                ProviderAuthStatus::Unknown
            }
        })
        .unwrap_or(ProviderAuthStatus::Unknown);
    ExternalAgentProviderStatus {
        discovered: true,
        auth,
    }
}

fn command_output(program: &OsStr, args: &[&str]) -> Option<(bool, String)> {
    let output = Command::new(program)
        .args(args)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
        .ok()?;
    let mut text = String::from_utf8_lossy(&output.stdout).into_owned();
    text.push_str(&String::from_utf8_lossy(&output.stderr));
    Some((output.status.success(), text))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generic_arguments_do_not_invoke_shell_parsing() {
        assert_eq!(
            direct_args("--flag value ; echo nope"),
            ["--flag", "value", ";", "echo", "nope"]
        );
    }

    #[test]
    fn first_class_mcp_plans_reference_token_environment_only() {
        for kind in [
            ExternalAgentProviderKind::ClaudeCode,
            ExternalAgentProviderKind::Codex,
        ] {
            let selection =
                ExternalAgentProviderSelection::new(kind, "", "").expect("selection");
            let plan = selection
                .launch_plan(
                    "http://127.0.0.1:4242/mcp",
                    ExternalAgentLaunchPurpose::BuildOrRepair,
                )
                .expect("plan");
            let args = plan
                .args
                .iter()
                .map(|arg| arg.to_string_lossy())
                .collect::<Vec<_>>()
                .join(" ");
            assert!(args.contains("GAMEENGINE_MCP_AUTH_TOKEN"));
            assert!(!args.contains("actual-secret-token"));
        }
    }

    #[test]
    fn provider_success_does_not_invent_completion() {
        for (kind, line) in [
            (ExternalAgentProviderKind::ClaudeCode, r#"{"type":"result","subtype":"success"}"#),
            (ExternalAgentProviderKind::Codex, r#"{"type":"turn.completed"}"#),
        ] {
            let events = semantic_event_payloads(kind, line);
            assert!(events.iter().all(|event| !event.contains("completion_gate")));
        }
    }

    #[test]
    fn structured_tool_event_omits_provider_input_and_path() {
        let line = r#"{"type":"item.completed","item":{"type":"command_execution","command":"secret command","aggregated_output":"C:\\private"}}"#;
        let events = semantic_event_payloads(ExternalAgentProviderKind::Codex, line).join("\n");
        assert!(events.contains("command_execution"));
        assert!(!events.contains("secret command"));
        assert!(!events.contains("C:\\\\private"));
    }

    #[test]
    fn diagnostics_are_sanitized() {
        let hint = classify_provider_diagnostic(
            ExternalAgentProviderKind::ClaudeCode,
            "network timed out at provider.example",
        )
        .expect("classified");
        let message = hint.message(ExternalAgentProviderKind::ClaudeCode);
        assert!(message.contains("Retryable."));
        assert!(!message.contains("provider.example"));
    }
}
